  score?: number;
  levels: Array<{ label: string; value: number }>;
  geometry?: ChartPatternGeometry;
  editable: boolean;
  family: ChartPatternFamily;
  priority: ScannerPriority;
  status: ScannerPatternMapStatus;
}

