74: export function aggregateBars(bars: OHLCBar[], timeframe: WorkspaceTimeframe): OHLCBar[] {
75:   if (timeframe === 'D') {
76:     return bars;
77:   }
78: 
79:   const groups = new Map<string, OHLCBar[]>();
80:   bars.forEach((bar) => {
81:     const date = parseISO(bar.date);
82:     const key = getAggregateGroupKey(date, timeframe);
83:     const group = groups.get(key) ?? [];
84:     group.push(bar);
85:     groups.set(key, group);
86:   });
87: 
88:   return [...groups.entries()].map(([key, group]) => {
89:     const first = group[0];
90:     const last = group[group.length - 1];
91:     return {
92:       date: getAggregateDisplayDate(first, key, timeframe),
93:       timestamp: first.timestamp,
94:       open: first.open,
95:       high: Math.max(...group.map((bar) => bar.high)),
96:       low: Math.min(...group.map((bar) => bar.low)),
97:       close: last.close,
