import { loadCompleteChartHistory } from '@/plugins/scanner/chartPatternScanService';

const receipts: unknown[] = [];
const sources = new Map<string, string>();
function parse(path: string) {
  const text = readFileSync(resolve(path), 'utf8');
  sources.set(path, createHash('sha256').update(text).digest('hex'));
  return ts.createSourceFile(path, text, ts.ScriptTarget.Latest, true, ts.ScriptKind.TSX);
}
function functions(path: string, names: string[]) {
  const source = parse(path);
  return names.map(name => {
    const node = source.statements.find(n => ts.isFunctionDeclaration(n) && n.name?.text === name);
    if (!node) throw new Error(`Missing production function ${path}:${name}`);
    return node.getText(source);
  }).join('\n');
}
function evaluate(code: string, globals: Record<string, unknown> = {}) {
  const context = vm.createContext({ exports: {}, ...globals });
  vm.runInContext(ts.transpileModule(code, { compilerOptions: { target: ts.ScriptTarget.ES2022, module: ts.ModuleKind.CommonJS } }).outputText, context);
  return context as any;
}
