const instrument = { exchange: 'NSE', symbol: 'ABC' };
const bars = Array.from({ length: 25 }, (_, index) => ({ date: `2028-06-${String(index + 1).padStart(2, '0')}`, open: 100, high: 110, low: 90, close: 100, volume: 100000, symbol: 'ABC' }));
function overlay(geometry: any, date = bars[19].date) {
