+  ].filter((level): level is { label: string; value: number } => typeof level.value === 'number' && Number.isFinite(level.value));
+  return { ...overlay, priceBasis: context.priceBasis, direction: result.direction, score: result.score,
+    geometry: details.geometry, levels, editable: details.geometry.family === 'range' };
