      { id: 'fib-l1', value: 0.618, enabled: false, text: 'Golden' },
      { id: 'fib-l2', value: 1.272, enabled: true, text: undefined },
    ]);
    expect(getFibonacciLevelSlotId(resolveFibonacciLevels(drawing, [0, 1])[1])).toBe('level:fib-l1');
  });

