      reverse: true,
      showPrices: false,
      logScaleLevels: false,
      coefficientFormat: 'percent',
      horizontalLabelPosition: 'right',
      verticalLabelPosition: 'top',
    });
  });

  it('formats coefficient labels without forcing percentages', () => {
